require_once __DIR__ . '/../../config/db.php';
require_once __DIR__ . '/../../core/_activity_viewer_template.php';

$activityId=trim((string)($_GET['id']??''));$unit=trim((string)($_GET['unit']??''));$returnTo=trim((string)($_GET['return_to']??''));
function ddpv_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function ddpv_items(array $raw):array{$items=[];foreach($raw as $k=>$i){if(!is_array($i))continue;$id=(int)($i['id']??0);$url=trim((string)($i['pic_url']??''));if($id<=0||$url==='')continue;$items[]=['id'=>$id,'pic_url'=>$url,'label'=>trim((string)($i['label']??'')),'x'=>max(0,min(96,(float)($i['x']??10))),'y'=>max(0,min(96,(float)($i['y']??10))),'w'=>max(4,min(60,(float)($i['w']??14))),'h'=>max(4,min(60,(float)($i['h']??12))),'rot'=>(((int)($i['rot']??0))%360+360)%360,'flipH'=>!empty($i['flipH']),'layer'=>max(0,(int)($i['layer']??$k))];}usort($items,fn($a,$b)=>$a['layer']<=>$b['layer']);foreach($items as $k=>&$i)$i['layer']=$k;unset($i);return $items;}
function ddpv_payload($raw):array{$d=is_string($raw)?json_decode($raw,true):$raw;if(!is_array($d))$d=[];$blocks=[];if(!empty($d['blocks'])&&is_array($d['blocks']))foreach($d['blocks'] as $k=>$b){if(!is_array($b))continue;$bg=trim((string)($b['background_image']??''));$items=ddpv_items($b['items']??[]);if($bg!==''&&$items)$blocks[]=['id'=>trim((string)($b['id']??''))?:('block_'.($k+1)),'title'=>trim((string)($b['title']??''))?:('Block '.($k+1)),'instructions'=>trim((string)($b['instructions']??'')),'background_image'=>$bg,'items'=>$items];}if(!$blocks){$bg=trim((string)($d['background_image']??''));$items=ddpv_items($d['items']??[]);if($bg!==''&&$items)$blocks[]=['id'=>'block_1','title'=>'Block 1','instructions'=>trim((string)($d['instructions']??'')),'background_image'=>$bg,'items'=>$items];}return['title'=>trim((string)($d['title']??''))?:'Drag & Drop Picture','instructions'=>trim((string)($d['instructions']??'')),'blocks'=>$blocks];}
if($unit===''&&$activityId!==''){$s=$pdo->prepare('SELECT unit_id FROM activities WHERE id=:id LIMIT 1');$s->execute(['id'=>$activityId]);$r=$s->fetch(PDO::FETCH_ASSOC);$unit=$r?(string)($r['unit_id']??''):'';}
$row=null;if($activityId!==''){$s=$pdo->prepare("SELECT id,data FROM activities WHERE id=:id AND type='dragdrop_pic' LIMIT 1");$s->execute(['id'=>$activityId]);$row=$s->fetch(PDO::FETCH_ASSOC);}if(!$row&&$unit!==''){$s=$pdo->prepare("SELECT id,data FROM activities WHERE unit_id=:unit AND type='dragdrop_pic' ORDER BY id ASC LIMIT 1");$s->execute(['unit'=>$unit]);$row=$s->fetch(PDO::FETCH_ASSOC);}if(!$row)die('Activity not configured yet.');
$activity=ddpv_payload($row['data']??null);$activityId=(string)($row['id']??$activityId);$title=$activity['title'];$instructions=$activity['instructions'];$blocks=$activity['blocks'];if(!$blocks)die('Activity not configured yet.');
$totalItems=array_sum(array_map(fn($b)=>count($b['items']),$blocks));
ob_start();
?>
<style>
body,.activity-wrapper,.viewer-content,body.presentation-mode .viewer-content,body.fullscreen-embedded .viewer-content{background:#fff!important}.ddpv-shell{max-width:1080px;margin:0 auto;padding:0 14px 24px;box-sizing:border-box}.ddpv-block-head{text-align:center;margin:0 0 8px}.ddpv-block-head h3{margin:0;color:#6158b7;font-size:clamp(18px,2.3vw,26px)}.ddpv-block-head p{margin:3px 0 0;color:#8d86b3}.ddpv-progress{font-weight:800;color:#7F77DD;margin-bottom:5px}.ddpv-toolbar{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin:0 0 10px}.ddpv-btn{border:2px solid #7F77DD;background:#fff;color:#6158b7;border-radius:999px;min-width:38px;height:38px;padding:0 13px;font-weight:800;cursor:pointer}.ddpv-btn.primary{background:#7F77DD;color:#fff}.ddpv-btn.warn{border-color:#F97316;color:#F97316}.ddpv-btn:disabled{opacity:.45}.ddpv-feedback{min-height:24px;text-align:center;font-weight:800;font-size:14px}.ddpv-feedback.good{color:#15803d}.ddpv-feedback.bad{color:#dc2626}.ddpv-stage-wrap{overflow:auto;-webkit-overflow-scrolling:touch;padding:4px 4px 10px}.ddpv-zoom-target{transform-origin:top center;transition:transform .15s ease}.ddpv-stage{display:flex;justify-content:center;align-items:flex-start}.ddpv-canvas{position:relative;display:inline-block;line-height:0;touch-action:none}.ddpv-bg{display:block;max-width:100%;max-height:calc(100vh - 330px);width:auto;height:auto;border-radius:18px;box-shadow:0 10px 28px rgba(15,23,42,.14);pointer-events:none;user-select:none}.ddpv-zone{position:absolute;box-sizing:border-box;border-radius:10px;touch-action:none;cursor:pointer}.ddpv-zone.over{outline:3px solid #F97316;outline-offset:-2px;background:rgba(249,115,22,.16)}.ddpv-zone.wrong{outline:3px solid #dc2626;outline-offset:-2px;background:rgba(220,38,38,.14);animation:shake .35s ease}.ddpv-zone.filled{pointer-events:none}.ddpv-placed{position:absolute;object-fit:contain;display:block;pointer-events:none;user-select:none;transform-origin:center}.ddpv-bank{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;min-height:92px;margin-top:10px;padding:8px;border:1px solid #ede9fa;background:#faf9ff;border-radius:16px}.ddpv-chip{width:92px;min-height:92px;display:flex;align-items:center;justify-content:center;border:2px solid #7F77DD;border-radius:14px;background:#fff;box-shadow:0 3px 10px rgba(127,119,221,.16);cursor:grab;touch-action:none;user-select:none}.ddpv-chip.selected{border-color:#F97316;box-shadow:0 0 0 3px rgba(249,115,22,.2)}.ddpv-chip.dragging{opacity:.25}.ddpv-chip img{width:84px;height:84px;object-fit:contain;pointer-events:none}.ddpv-drag-image{position:fixed;z-index:100000;pointer-events:none;width:96px;height:96px;object-fit:contain;filter:drop-shadow(0 10px 15px rgba(0,0,0,.3))}.ddpv-next-wrap{text-align:center;margin-top:12px}.ddpv-completed{margin-top:12px}@keyframes shake{25%{transform:translateX(-7px)}75%{transform:translateX(7px)}}@media(max-width:700px){.ddpv-shell{padding-left:6px;padding-right:6px}.ddpv-bg{max-height:none;max-width:none;width:min(94vw,760px)}.ddpv-chip{width:76px;min-height:76px}.ddpv-chip img{width:68px;height:68px}}
